# ---------------------------------------------------------------------------
# Filter lookup helpers
# ---------------------------------------------------------------------------

def normalize_filter_name(raw_name: str) -> str:
    """Normalize a filter name from FITS header."""
    if not raw_name:
        return ''

    name = raw_name.strip()
    name_upper = name.upper()

    # Direct alias lookup
    if name_upper in FILTER_ALIASES:
        return FILTER_ALIASES[name_upper]

    # Try database key directly
    if name in FILTERS_DATABASE:
        return name

    # Case-insensitive database match
    for key in FILTERS_DATABASE:
        if key.upper() == name_upper:
            return key

    # Partial matching for branded filters
    for alias_key, canonical in FILTER_ALIASES.items():
        if alias_key in name_upper:
            return canonical

    return name


def lookup_filter(raw_name: str) -> Optional[Dict[str, Any]]:
    """Look up filter info from FITS header filter name."""
    canonical = normalize_filter_name(raw_name)

    if canonical in FILTERS_DATABASE:
        return FILTERS_DATABASE[canonical]

    # Case-insensitive fallback
    for key, info in FILTERS_DATABASE.items():
        if key.upper() == canonical.upper():
            return info

    return None


def get_filter_type(raw_name: str) -> Optional[str]:
    """Get filter type classification."""
    info = lookup_filter(raw_name)
    return info['type'] if info else None


def is_narrowband(raw_name: str) -> bool:
    """Check if a filter is narrowband."""
    ftype = get_filter_type(raw_name)
    return ftype in ('narrowband', 'dual_narrowband')


def get_filter_wavelength(raw_name: str) -> Optional[float]:
    """Get center wavelength in nm."""
    info = lookup_filter(raw_name)
    return info['center_nm'] if info and info['center_nm'] > 0 else None


def classify_filter_set(filter_names: List[str]) -> Dict[str, str]:
    """
    Classify a set of filter names into their canonical types.
    Returns dict of {original_name: canonical_name}.
    """
    result = {}
    for name in filter_names:
        result[name] = normalize_filter_name(name)
    return result


def detect_palette(filter_names: List[str]) -> str:
    """
    Detect the imaging palette from a set of filters.
    Returns: 'LRGB', 'SHO', 'HOO', 'RGB', 'Mono L', 'Duo NB', 'Mixed', etc.
    """
    canonical = set(normalize_filter_name(f) for f in filter_names if f)

    has_l = 'L' in canonical
    has_r = 'R' in canonical
    has_g = 'G' in canonical
    has_b = 'B' in canonical
    has_ha = 'Ha' in canonical
    has_oiii = 'OIII' in canonical
    has_sii = 'SII' in canonical
    has_duo = any(lookup_filter(f) and lookup_filter(f).get('type') == 'dual_narrowband'
                  for f in filter_names if f)

    if has_ha and has_sii and has_oiii:
        return 'SHO (Hubble)'
    elif has_ha and has_oiii and not has_sii:
        return 'HOO'
    elif has_l and has_r and has_g and has_b:
        return 'LRGB'
    elif has_r and has_g and has_b and not has_l:
        return 'RGB'
    elif has_duo:
        return 'Dual Narrowband'
    elif has_l and len(canonical) == 1:
        return 'Mono L'
    elif has_ha and len(canonical) == 1:
        return 'Ha only'
    elif len(canonical) == 0:
        return 'Unknown'
    else:
        return 'Mixed'


def list_filters_by_type() -> Dict[str, List[str]]:
    """Return filters grouped by type."""
    by_type = {}
    for key, info in FILTERS_DATABASE.items():
        ftype = info.get('type', 'unknown')
        if ftype not in by_type:
            by_type[ftype] = []
        by_type[ftype].append(key)
    return by_type
